node src/cli.ts kill al-profile --form manual --text "The same class of trade-off comes up a second time, so a standing preference would have answered it." && cat > /tmp/prop-profile.mjs <<'EOF'
import { spawnSync } from 'node:child_process'
const root = '/Users/eryk.napierala/conductor/workspaces/werk/iqaluit'
const { splitBlocks } = await import(`${root}/web/diff.js`)
const { fold } = await import(`${root}/src/fold.ts`)
const { readEvents } = await import(`${root}/src/log.ts`)
const [idea, skip] = splitBlocks(fold(readEvents()).nodes.get('al-profile').body)
const r = spawnSync('node', ['src/cli.ts', 'propose', 'al-profile',
  '--why', 'No standing-preference mechanism until the same class of trade-off comes up twice. A one-off decision does not earn one.',
  '--ops', JSON.stringify([
    { tag: 'elaborated', old: idea, new: 'The idea holds: a profile captures how the user decides, not what to build, so alignment does not reset with every work item. It pays off only when a trade-off repeats. The decisions on the map each settle a distinct trade-off: #werk-stack\'s six criteria, the tab placement, the permission mode. A profile mechanism for them would be process with nothing to serve.' },
    { tag: 'elaborated', old: skip, new: 'The kill criterion holds the trigger: the same class of trade-off a second time. #decisionmd is the starting point when it fires.' },
  ])], { cwd: root, encoding: 'utf8' })
console.log(r.stdout, r.stderr)
EOF
bun /tmp/prop-profile.mjs
